insert into T_MDM_MONTH_PLAN_ANALYSIS (id,month_plan_aps_version,material_code, embryo_code,quality_grade,storage_location, special_requirements,actual_arrangement,cx_month_plan_qty, tm_code,tm_month_plan_qty,tc_code, tc_month_plan_qty,nc_code,nc_month_plan_qty, tq_code,tq_month_plan_qty,gsq_code, gsq_month_plan_qty,gdcd_month_plan_qty,cd15_one_code, cd15_one_month_plan_qty,cd15_two_code,cd15_two_month_plan_qty, lbcd_month_plan_qty,cd90_one_code,cd90_one_month_plan_qty, cd90_two_code,cd90_two_month_plan_qty,cd90_three_code, cd90_three_month_plan_qty,gdyy_code,gdyy_month_plan_qty, gdyy_month_plan_num_qty,xwyy_code,xwyy_month_plan_qty, xwyy_month_plan_num_qty,remark,del_flag, create_by,create_time,update_by, update_time,BOM_DATA_VERSION) select T_MDM_MONTH_PLAN_ANALYSIS_SEQ.NEXTVAL AS ID, x.* from (
select #{item.monthPlanApsVersion,jdbcType=VARCHAR},#{item.materialCode,jdbcType=VARCHAR}, #{item.embryoCode,jdbcType=VARCHAR},#{item.qualityGrade,jdbcType=VARCHAR},#{item.storageLocation,jdbcType=VARCHAR}, #{item.specialRequirements,jdbcType=VARCHAR},#{item.actualArrangement,jdbcType=NUMERIC},#{item.cxMonthPlanQty,jdbcType=NUMERIC}, #{item.tmCode,jdbcType=VARCHAR},#{item.tmMonthPlanQty,jdbcType=NUMERIC},#{item.tcCode,jdbcType=VARCHAR}, #{item.tcMonthPlanQty,jdbcType=DECIMAL},#{item.ncCode,jdbcType=VARCHAR},#{item.ncMonthPlanQty,jdbcType=DECIMAL}, #{item.tqCode,jdbcType=VARCHAR},#{item.tqMonthPlanQty,jdbcType=DECIMAL},#{item.gsqCode,jdbcType=VARCHAR}, #{item.gsqMonthPlanQty,jdbcType=DECIMAL},#{item.gdcdMonthPlanQty,jdbcType=DECIMAL},#{item.cd15OneCode,jdbcType=VARCHAR}, #{item.cd15OneMonthPlanQty,jdbcType=DECIMAL},#{item.cd15TwoCode,jdbcType=VARCHAR},#{item.cd15TwoMonthPlanQty,jdbcType=DECIMAL}, #{item.lbcdMonthPlanQty,jdbcType=DECIMAL},#{item.cd90OneCode,jdbcType=VARCHAR},#{item.cd90OneMonthPlanQty,jdbcType=DECIMAL}, #{item.cd90TwoCode,jdbcType=VARCHAR},#{item.cd90TwoMonthPlanQty,jdbcType=DECIMAL},#{item.cd90ThreeCode,jdbcType=VARCHAR}, #{item.cd90ThreeMonthPlanQty,jdbcType=DECIMAL},#{item.gdyyCode,jdbcType=VARCHAR},#{item.gdyyMonthPlanQty,jdbcType=DECIMAL}, #{item.gdyyMonthPlanNumQty,jdbcType=NUMERIC},#{item.xwyyCode,jdbcType=VARCHAR},#{item.xwyyMonthPlanQty,jdbcType=DECIMAL}, #{item.xwyyMonthPlanNumQty,jdbcType=NUMERIC},#{item.remark,jdbcType=VARCHAR},#{item.delFlag,jdbcType=VARCHAR}, #{item.createBy,jdbcType=VARCHAR},#{item.createTime,jdbcType=TIMESTAMP},#{item.updateBy,jdbcType=VARCHAR}, #{item.updateTime,jdbcType=TIMESTAMP},#{item.bomDataVersion,jdbcType=VARCHAR} from dual
) x
